query getProduct($id: String!, $market: MarketType!) {
  product(id: $id, market: $market) {
    applicationDescription
    productGroup { name }
    specifications { description value }
    id
    partNumber
    crossReferences {
      brand {
        name
      }
      partNumber
    }
    vehicles {
      brand
      name
      model
      engineName
      engineConfiguration
      startYear
      endYear
      note
      only
      restriction
    }
    images {
      imageUrl
    }
  }
}

